37: /**
38:  * 获取当前导航栈实例
39:  * @returns {NavPathStack | undefined} 导航栈实例；未初始化时返回 undefined
40:  */
41: export function getNavPathStack(): NavPathStack | undefined {
42:   if (!globalNavStack) {
43:     const msg: string = "[NavigationService] nav stack is not initialized, call setNavPathStack first.";
44:     hilog.error(DOMAIN, "NavSvc", msg);
45:     return undefined;
46:   }
47:   return globalNavStack;
48: }
