54:  * @returns {void} 无返回值
55:  */
56: export function navigateTo(name: string, params: NavParams = {}): void {
57:   if (requiresLogin(name)) {
58:     const userState = getUserState();
59:     if (!userState.isLoggedIn()) {
60:       hilog.info(DOMAIN, "NavSvc", `[NavigationService] Intercepting route to ${name}, redirecting to Login`);
61:       name = getLoginRoute();
