65:   const stack: NavPathStack | undefined = getNavPathStack();
66:   if (!stack) {
67:     return;
68:   }
69:   try {
70:     stack.pushPath({
71:       name: name,
72:       param: params
73:     });
74:   } catch (err) {
75:     hilog.error(DOMAIN, "NavSvc", "[NavigationService] navigateTo failed: %{public}s", JSON.stringify(err));
76:   }
77: }
