101: export function navigateBackWithResult(result: NavParams | object = {}, animated?: boolean): void {
102:   const stack: NavPathStack | undefined = getNavPathStack();
103:   if (!stack) {
104:     return;
105:   }
106:   try {
107:     stack.pop(result, animated);
108:   } catch (err) {
109:     hilog.error(DOMAIN, "NavSvc", "[NavigationService] navigateBackWithResult failed: %{public}s", JSON.stringify(err));
110:   }
111: }
