133:  * @param {string} name - 路由名称
134:  * @param {Any} [params={}] - 跳转参数
135:  * @param {(info: PopInfo) => void} [onPop] - 返回结果回调（在目标页调用 pop(result) 时触发）
136:  * @returns {Promise<void>} 跳转完成 Promise
137:  */
138: export function navigateToWithResult(name: string, params: NavParams = {},
139:   onPop?: (info: PopInfo) => void): Promise<void> {
140:   if (requiresLogin(name)) {
141:     const userState = getUserState();
142:     if (!userState.isLoggedIn()) {
143:       hilog.info(DOMAIN, "NavSvc", `[NavigationService] Intercepting route to ${name}, redirecting to Login`);
