146:   }
147: 
148:   const stack: NavPathStack | undefined = getNavPathStack();
149:   if (!stack) {
150:     return Promise.resolve();
151:   }
152: 
153:   const safeParam: Object = params as Object;
154:   try {
155:     if (onPop) {
156:       return stack.pushDestinationByName(name, safeParam, onPop).catch((err: Any) => {
157:         hilog.error(DOMAIN, "NavSvc", "[NavigationService] navigateToWithResult failed: %{public}s",
158:           JSON.stringify(err));
159:       });
160:     }
161:     return stack.pushDestinationByName(name, safeParam).catch((err: Any) => {
162:       hilog.error(DOMAIN, "NavSvc", "[NavigationService] navigateToWithResult failed: %{public}s", JSON.stringify(err));
163:     });
164:   } catch (err) {
165:     hilog.error(DOMAIN, "NavSvc", "[NavigationService] navigateToWithResult failed: %{public}s", JSON.stringify(err));
166:     return Promise.resolve();
167:   }
168: }
